using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class SensitiveFieldTests
{
 class User(int employee=4,params string[] grants):ICurrentUser{public string Email=>"privacy@example.local";public int? EmployeeId=>employee;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>false;public bool Can(string p)=>grants.Contains(p);}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static EmployeeService S(AppDbContext d,User u){var c=new AppClock(TimeProvider.System);return new(d,new AccessScope(d,u),u,new AuditService(d,u,c),c);}
 [Fact]public async Task CompanyScopeAndSalaryGrantDoNotExposeIdentityOrBank(){await using var d=await Db();var e=(await d.Set<Employee>().FindAsync(6))!;e.NationalId="29006110000001";e.Address="Private address";e.Iban="PRIVATE-BANK";await d.SaveAsync();var u=new User(4,Perm.ScopeCompany,Perm.EmpSalary);var v=await S(d,u).ProfileAsync(6);Assert.False(v.CanSeeIdentity);Assert.False(v.CanSeeBank);Assert.Equal("",v.Employee.NationalId);Assert.Equal("",v.Employee.Iban);Assert.Equal("",v.Employee.Address);Assert.Equal(e.BasicSalary,v.Employee.BasicSalary);Assert.Equal("PRIVATE-BANK",e.Iban);}
 [Fact]public async Task OwnerAndIndependentGrantsAreHonored(){await using var d=await Db();var e=(await d.Set<Employee>().FindAsync(6))!;e.NationalId="29006110000001";e.Iban="PRIVATE-BANK";await d.SaveAsync();var own=await S(d,new User(6)).ProfileAsync(6);Assert.Equal(e.NationalId,own.Employee.NationalId);Assert.Equal(e.Iban,own.Employee.Iban);var identity=await S(d,new User(4,Perm.ScopeCompany,Perm.EmpIdentity)).ProfileAsync(6);Assert.True(identity.CanSeeIdentity);Assert.False(identity.CanSeeBank);Assert.Equal(e.NationalId,identity.Employee.NationalId);Assert.Equal("",identity.Employee.Iban);var bank=await S(d,new User(4,Perm.ScopeCompany,Perm.EmpBank)).ProfileAsync(6);Assert.True(bank.CanSeeBank);Assert.False(bank.CanSeeIdentity);Assert.Equal(e.Iban,bank.Employee.Iban);}
 [Fact]public async Task EditModelAndTamperedPostCannotUseGeneralHrOrPayGrantForPrivateFields(){await using var d=await Db();var e=(await d.Set<Employee>().FindAsync(6))!;e.NationalId="29006110000001";e.Iban="PRIVATE-BANK";e.InsuranceNumber="PRIVATE-INS";await d.SaveAsync();var svc=S(d,new User(4,Perm.EmpManage,Perm.EmpPay));var model=(await svc.EditModelAsync(6))!;Assert.Equal("",model.NationalId);Assert.Equal("",model.Iban);model.NationalId="29006110000002";model.Iban="TAMPER";model.Address="TAMPER";await svc.SaveAsync(model,"Fictional privacy test");Assert.Equal("29006110000001",e.NationalId);Assert.Equal("PRIVATE-BANK",e.Iban);Assert.Equal("PRIVATE-INS",e.InsuranceNumber);}
 [Fact]public async Task MedicalLeaveEvidenceNeedsIndependentGrantAndDirectFileGuard(){await using var d=await Db();var type=await d.Set<LeaveType>().FirstAsync(x=>x.Code=="SICK");var f=new Attachment{OwnerEmployeeId=6,FileName="private.pdf",Data="%PDF-test"u8.ToArray()};d.Add(f);await d.SaveAsync();var r=new LeaveRequest{EmployeeId=6,LeaveTypeId=type.Id,Route="Manager",AttachmentToken=f.Token,AttachmentName=f.FileName,StartDate=new(2026,12,1),EndDate=new(2026,12,1),Days=1,Comment="Private medical reason"};d.Add(r);await d.SaveAsync();var u=new User(4,Perm.ScopeCompany);var c=new AppClock(TimeProvider.System);ApprovalService A(User who){var a=new AuditService(d,who,c);return new(d,new AccessScope(d,who),who,a,new NotificationService(d,who,c),c,new WorkflowService(d,who,a),new DelegationService(d,who,a,c));}var row=Assert.Single((await A(u).ListAsync("Leave",null,false)).Where(x=>x.Id==r.Id));Assert.Equal("Private leave",row.TypeName);Assert.Null(row.AttachmentToken);Assert.Null(row.Comment);await Assert.ThrowsAsync<DomainException>(()=>new AttachmentService(d,new AccessScope(d,u),u,c).GetAsync(f.Token));var authorized=new User(4,Perm.ScopeCompany,Perm.LeaveEvidence);row=Assert.Single((await A(authorized).ListAsync("Leave",null,false)).Where(x=>x.Id==r.Id));Assert.Equal(type.Name,row.TypeName);Assert.Equal(f.Token,row.AttachmentToken);Assert.NotNull(await new AttachmentService(d,new AccessScope(d,authorized),authorized,c).GetAsync(f.Token));}
 [Fact]public async Task LeaveLedgerForOtherEmployeeIsWithheldWithoutEvidenceGrant(){await using var d=await Db();var u=new User(4,Perm.ScopeCompany);var c=new AppClock(TimeProvider.System);var audit=new AuditService(d,u,c);var svc=new LeaveService(d,new AccessScope(d,u),u,audit,new NotificationService(d,u,c),c,new WorkflowService(d,u,audit));d.Add(new LeaveTransaction{EmployeeId=6,LeaveTypeId=1,Year=2026,Delta=1,Reason="Private health evidence",Kind="Adjustment"});await d.SaveAsync();Assert.Empty(await svc.TransactionsAsync(6,2026));await Assert.ThrowsAsync<DomainException>(()=>svc.BalancesAsync(6,2026));var owner=new User(6);audit=new AuditService(d,owner,c);var ownSvc=new LeaveService(d,new AccessScope(d,owner),owner,audit,new NotificationService(d,owner,c),c,new WorkflowService(d,owner,audit));Assert.Contains(await ownSvc.TransactionsAsync(6,2026),x=>x.Reason=="Private health evidence");}

 [Fact]public async Task HistoricalFreeTextAndSalaryAreRedactedWithoutChangingOriginals(){await using var d=await Db();d.Add(new CareerEvent{EmployeeId=6,Type=CareerEventType.Transfer,Details="Private identity reason"});d.Add(new StatusHistory{EmployeeId=6,Reason="Private status reason"});d.Add(new Contract{EmployeeId=6,Notes="Private contract"});d.Add(new EmployeeAssignment{EmployeeId=6,BasicSalary=12345,Reason="Private assignment"});d.Add(new EmploymentChange{EmployeeId=6,BasicSalary=9999,Reason="Private future reason"});await d.SaveAsync();var u=new User(4,Perm.ScopeCompany);var svc=S(d,u);var p=await svc.ProfileAsync(6);Assert.All(p.Events,x=>Assert.Equal("",x.Details));Assert.All(p.StatusHistory,x=>Assert.Null(x.Reason));Assert.All(p.Contracts,x=>Assert.Equal("",x.Notes));var h=await svc.AssignmentsAsync(6);Assert.All(h,x=>{Assert.Equal(0,x.BasicSalary);Assert.Equal("",x.Reason);});var c=new AppClock(TimeProvider.System);var future=await new EmploymentTimeline(d,u,c,new AuditService(d,u,c)).ListAsync(6,new AccessScope(d,u));Assert.All(future,x=>{Assert.Equal(0,x.BasicSalary);Assert.Equal("",x.Reason);});Assert.Equal("Private assignment",(await d.Set<EmployeeAssignment>().FirstAsync(x=>x.EmployeeId==6)).Reason);Assert.Contains(await d.Set<CareerEvent>().ToListAsync(),x=>x.Details=="Private identity reason");}
 [Fact]public async Task ListAndManagerPickersOnlyReturnAuthorizedPrivateFields(){await using var d=await Db();var e=(await d.Set<Employee>().FindAsync(6))!;e.NationalId="29006110000001";e.Iban="PRIVATE";await d.SaveAsync();var svc=S(d,new User(4,Perm.ScopeCompany));var list=await svc.SearchAsync(new(null,null,null,null));var row=Assert.Single(list.Where(x=>x.Id==6));Assert.Equal("",row.Iban);Assert.Equal("",row.NationalId);Assert.Equal(0,row.BasicSalary);row=Assert.Single((await svc.ManagerCandidatesAsync()).Where(x=>x.Id==6));Assert.Equal("",row.Iban);Assert.Equal(0,row.BasicSalary);Assert.Equal("PRIVATE",e.Iban);}

 [Fact]public async Task LeaveReportOmitsOtherEmployeesBalancesWithoutEvidencePermission(){await using var d=await Db();var u=new User(4,Perm.ScopeCompany,Perm.Reports);var c=new AppClock(TimeProvider.System);ReportService R(User who){var scope=new AccessScope(d,who);var audit=new AuditService(d,who,c);var notify=new NotificationService(d,who,c);var flows=new WorkflowService(d,who,audit);return new(d,scope,who,new AttendanceService(d,scope,who,audit,notify,c,flows),new ApprovalService(d,scope,who,audit,notify,c,flows,new DelegationService(d,who,audit,c)),S(d,who),new LeaveService(d,scope,who,audit,notify,c,flows),c);}var table=await R(u).BuildAsync("leave",2026,11);var ownCode=(await d.Set<Employee>().FindAsync(4))!.Code;Assert.All(table.Rows,x=>Assert.Equal(ownCode,x[0]));var allowed=await R(new User(4,Perm.ScopeCompany,Perm.Reports,Perm.LeaveEvidence)).BuildAsync("leave",2026,11);Assert.True(allowed.Rows.Count>table.Rows.Count);}

 [Fact]public async Task CustomLeaveReportMasksEvidenceTypeUnlessIndependentlyGranted(){await using var d=await Db();d.Add(new LeaveRequest{EmployeeId=6,LeaveTypeId=1,StartDate=new(2026,12,1),EndDate=new(2026,12,1),Days=1});await d.SaveAsync();var user=new User(4,Perm.ScopeCompany,Perm.Reports);var report=await new ReportBuilderService(d,new AccessScope(d,user),user).RunAsync("leave",["code","type"],null);var code=(await d.Set<Employee>().FindAsync(6))!.Code;Assert.All(report.Rows.Where(x=>x[0]==code),x=>Assert.Equal("Private leave",x[1]));var allowed=new User(4,Perm.ScopeCompany,Perm.Reports,Perm.LeaveEvidence);report=await new ReportBuilderService(d,new AccessScope(d,allowed),allowed).RunAsync("leave",["code","type"],null);Assert.Contains(report.Rows,x=>x[0]==code&&x[1]!="Private leave");}

 [Fact]public async Task FinancialExportsRequireSeparateSensitiveFieldGrants(){await using var d=await Db();var u=new User(4,Perm.PayExport,Perm.PayView);var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);var n=new NotificationService(d,u,c);var scope=new AccessScope(d,u);var svc=new PayrollService(d,u,a,n,new AttendanceService(d,scope,u,a,n,c,new WorkflowService(d,u,a)),c);await Assert.ThrowsAsync<DomainException>(()=>svc.BankFileAsync(1));await Assert.ThrowsAsync<DomainException>(()=>svc.SnapshotFileAsync(1));d.Add(new PayrollCalculationSnapshot{RunId=1,Version=1,Payload="PRIVATE BANK AND NOTES",Sha256="FAKE-DEMO",At=c.UtcNow});await d.SaveAsync();var list=await svc.SnapshotsAsync(1);Assert.All(list,x=>Assert.Equal("",x.Payload));Assert.Contains(await d.Set<PayrollCalculationSnapshot>().ToListAsync(),x=>x.Payload=="PRIVATE BANK AND NOTES");}
 [Fact]public async Task AttendanceCalendarDoesNotLeakPrivateLeaveTypeOrEvidence(){await using var d=await Db();var type=await d.Set<LeaveType>().FirstAsync(x=>x.Code=="SICK");var r=new LeaveRequest{EmployeeId=6,LeaveTypeId=type.Id,StartDate=new(2026,12,20),EndDate=new(2026,12,20),Days=1,Status=RequestStatus.Approved,Reason="Private medical detail",AttachmentToken="private-token"};d.Add(r);await d.SaveAsync();AttendanceService A(User u){var c=new AppClock(TimeProvider.System);var a=new AuditService(d,u,c);return new(d,new AccessScope(d,u),u,a,new NotificationService(d,u,c),c,new WorkflowService(d,u,a));}var row=(await A(new User(4,Perm.ScopeCompany)).MonthAsync(6,2026,12)).Single(x=>x.Date.Day==20);Assert.Equal("Private leave",row.Leave!.LeaveType!.Name);Assert.Null(row.Leave.Reason);Assert.Null(row.Leave.AttachmentToken);Assert.Null(row.Leave.Employee);Assert.Equal(type.Name,r.LeaveType!.Name);foreach(var u in new[]{new User(6),new User(4,Perm.ScopeCompany,Perm.LeaveEvidence)}){row=(await A(u).MonthAsync(6,2026,12)).Single(x=>x.Date.Day==20);Assert.Equal(type.Name,row.Leave!.LeaveType!.Name);Assert.Null(row.Leave.Reason);}}
 [Fact]public async Task DirectEmployeeReadsAreScopedDetachedAndRedacted(){await using var d=await Db();var e=(await d.Set<Employee>().FindAsync(6))!;e.Iban="PRIVATE";await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>S(d,new User(4)).GetAsync(6));var v=(await S(d,new User(4,Perm.ScopeCompany)).GetAsync(6))!;Assert.Equal("",v.Iban);Assert.Equal(0,v.BasicSalary);Assert.NotSame(e,v);Assert.Equal("PRIVATE",e.Iban);}
 [Fact]public async Task SettlementReadRequiresPayGrantAndHasNoIdentityOrBank(){await using var d=await Db();await Assert.ThrowsAsync<DomainException>(()=>S(d,new User(4,Perm.ScopeCompany)).SettlementEmployeeAsync(6));var e=(await d.Set<Employee>().FindAsync(6))!;e.Iban="PRIVATE";var v=(await S(d,new User(4,Perm.EmpPay)).SettlementEmployeeAsync(6))!;Assert.Equal(e.BasicSalary,v.BasicSalary);Assert.Equal(e.HireDate,v.HireDate);Assert.Equal("",v.Iban);Assert.Equal("",v.NationalId);}
 [Fact]public async Task ContractExpiryReadRedactsEmployeeAndContractWithoutMutatingSources(){await using var d=await Db();var e=(await d.Set<Employee>().FindAsync(6))!;e.Iban="PRIVATE";var c=new Contract{EmployeeId=6,StartDate=DateTime.Today.AddMonths(-1),EndDate=DateTime.Today.AddDays(1),Notes="Private contract",IsCurrent=true};d.Add(c);await d.SaveAsync();var row=Assert.Single((await S(d,new User(4,Perm.ScopeCompany)).ExpiringContractsAsync(60)).Where(x=>x.Contract.Id==c.Id));Assert.Equal("",row.Contract.Notes);Assert.Equal("",row.Employee.Iban);Assert.Equal(0,row.Employee.BasicSalary);Assert.Equal("Private contract",c.Notes);Assert.Equal("PRIVATE",e.Iban);}
}
